package com.rootopathy.careos.administration.api;
import com.rootopathy.careos.administration.application.OrganizationUnitException; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
@RestControllerAdvice(assignableTypes=OrganizationUnitController.class) public class OrganizationUnitProblemHandler extends ResponseEntityExceptionHandler {@ExceptionHandler(OrganizationUnitException.class) ResponseEntity<ProblemDetail> handle(OrganizationUnitException e,HttpServletRequest r){var status=switch(e.reason()){case PRECONDITION_REQUIRED->HttpStatus.PRECONDITION_REQUIRED;case STALE->HttpStatus.PRECONDITION_FAILED;case CONFLICT->HttpStatus.CONFLICT;case NOT_FOUND->HttpStatus.NOT_FOUND;};var p=ProblemDetail.forStatusAndDetail(status,e.getMessage());p.setTitle("Organization unit request failed");p.setType(java.net.URI.create("https://careos.local/problems/organization-unit-"+e.reason().name().toLowerCase().replace('_','-')));p.setInstance(java.net.URI.create(r.getRequestURI()));return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(p);}}
